import{_ as e,c as r,o as t,b0 as o}from"./chunks/framework.Dmsv_Tiv.js";const i="/media-docs/assets/image-20251110195438580.DvYXg3NW.png",l="/media-docs/assets/image-20251111091631264.ALcKo4lO.png",n="/media-docs/assets/image-20251111093010382.CsP8pOLg.png",p="/media-docs/assets/image-20251111091710490.CGtThMxS.png",s="/media-docs/assets/image-20251110195916353.CY3rI9lG.png",c="/media-docs/assets/image-20251111112842138.BWcBA0Dl.png",C=JSON.parse('{"title":"LV005-MIPI-Sensor接口原理图","description":null,"frontmatter":{"title":"LV005-MIPI-Sensor接口原理图","date":"2025-11-10T18:17:32.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/mipi/dphy/126b143a8b643417e9e21932","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-11-10T18:17:32.833Z","fulluuid":"7e9e2193203447d691810fad4e825a34","useduuid":"7e9e21932"}},"headers":[],"relativePath":"sdoc/mipi/dphy/126b143a8b643417e9e21932.md","filePath":"sdoc/15-MIPI/15-D-PHY/LV005-MIPI-Sensor接口原理图.md","lastUpdated":1767537778000}'),h={name:"sdoc/mipi/dphy/126b143a8b643417e9e21932.md"};function _(d,a,m,P,u,I){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="lv005-mipi-sensor接口原理图" tabindex="-1">LV005-MIPI-Sensor接口原理图 <a class="header-anchor" href="#lv005-mipi-sensor接口原理图" aria-label="Permalink to &quot;LV005-MIPI-Sensor接口原理图&quot;">​</a></h1><p>后面准备学习一下 D-PHY 接口，在学习之前，我们先来看一个实际的 MIPI 接口的 Sensor 电路原理图。</p><h2 id="一、rk3568-camera-接口" tabindex="-1">一、RK3568 Camera 接口 <a class="header-anchor" href="#一、rk3568-camera-接口" aria-label="Permalink to &quot;一、RK3568 Camera 接口&quot;">​</a></h2><h3 id="_1-相关资料" tabindex="-1">1. 相关资料 <a class="header-anchor" href="#_1-相关资料" aria-label="Permalink to &quot;1. 相关资料&quot;">​</a></h3><p>鲁班猫 2 使用的是 RK3568 的主控芯片，一些相关资料如下：</p><ul><li><p><a href="https://opensource.rock-chips.com/images/2/26/Rockchip_RK3568_TRM_Part1_V1.3-20220930P.PDF" target="_blank" rel="noreferrer">Rockchip RK3568 TRM Part1 V1.3-20220930P</a></p></li><li><p><a href="https://opensource.rock-chips.com/images/b/b6/Rockchip_RK3568_Datasheet_V1.3-20220929P.PDF" target="_blank" rel="noreferrer">Rockchip_RK3568_Datasheet_V1.3-20220929P</a></p></li><li><p><a href="https://gitee.com/rockchip-dev/document/raw/master/RockChip%E5%AE%98%E6%96%B9%E6%96%87%E6%A1%A3/Rockchip_RK3568_TRM_Part2_V1.1-20210301.pdf" target="_blank" rel="noreferrer">Rockchip_RK3568_TRM_Part2_V1.1-20210301.pdf</a></p></li></ul><h3 id="_2-mipi-接口" tabindex="-1">2. MIPI 接口 <a class="header-anchor" href="#_2-mipi-接口" aria-label="Permalink to &quot;2. MIPI 接口&quot;">​</a></h3><p>查看 <a href="https://opensource.rock-chips.com/images/b/b6/Rockchip_RK3568_Datasheet_V1.3-20220929P.PDF" target="_blank" rel="noreferrer">Rockchip_RK3568_Datasheet_V1.3-20220929P</a>，MIPI Interface 接口如下：</p><p><img src="'+i+'" alt="image-20251110195438580"></p><p>还可以参考《<a href="https://gitee.com/rockchip-dev/document/raw/master/RockChip%E5%AE%98%E6%96%B9%E6%96%87%E6%A1%A3/Rockchip_RK3568_TRM_Part2_V1.1-20210301.pdf" target="_blank" rel="noreferrer">Rockchip_RK3568_TRM_Part2_V1.1-20210301.pdf</a>》的 Chapter 28 MIPI CSI DPHY 这一节，这里描述了 RK3568 的 CSI DPHY 相关内容，从 28.1 Overview 这一部分我们可以知道，MIPI CSI DPHY 的特点如下：</p><ul><li><p>根据 MIPI v1.2 规范设计</p></li><li><p>集成了 PHY 协议接口（PPI），支持 DSI/CSI 和 UniPro MIPI 协议</p></li><li><p>每通道最大数据传输速率为 2.5 Gbps</p></li><li><p>可扩展至支持 4 个数据通道，提供高达 10gbps 的传输速率</p></li><li><p>低功耗模式下每通道 10Mbps</p></li><li><p>支持单向和双向模式</p></li></ul><h2 id="二、ov8858" tabindex="-1">二、OV8858 <a class="header-anchor" href="#二、ov8858" aria-label="Permalink to &quot;二、OV8858&quot;">​</a></h2><h3 id="_1-相关资料-1" tabindex="-1">1. 相关资料 <a class="header-anchor" href="#_1-相关资料-1" aria-label="Permalink to &quot;1. 相关资料&quot;">​</a></h3><p>用的野火的 OV8858 摄像头模块：<a href="https://doc.embedfire.com/products/link/zh/latest/module/camera/ov8858.html" target="_blank" rel="noreferrer">野火【摄像头_OV8858】模块</a>，数据手册和电路原理图如下：</p><ul><li><a href="https://gitee.com/rockchip-dev/document/raw/master/hardware/005-OV8858/EBF410127v1_SCH_20230426.pdf" target="_blank" rel="noreferrer">EBF410127v1_SCH_20230426.pdf</a></li><li><a href="https://gitee.com/rockchip-dev/document/raw/master/hardware/005-OV8858/OV8858COB_(rev%202A)_DS_2.0_Chippack.pdf" target="_blank" rel="noreferrer">OV8858_DS.book</a></li></ul><h3 id="_2-ov8858-摄像头接口" tabindex="-1">2. OV8858 摄像头接口 <a class="header-anchor" href="#_2-ov8858-摄像头接口" aria-label="Permalink to &quot;2. OV8858 摄像头接口&quot;">​</a></h3><table><tbody><tr style="border:none;"><td align="center" style="border:none;"><img src="'+l+'" style="width:80%;height:auto;"></td><td align="center" style="border:none;"><img src="'+n+'" style="width:80%;height:auto;"></td></tr></tbody></table><h3 id="_3-24m-时钟" tabindex="-1">3. 24M 时钟 <a class="header-anchor" href="#_3-24m-时钟" aria-label="Permalink to &quot;3. 24M 时钟&quot;">​</a></h3><p>sensor 这里有一个外部 24M 时钟：</p><p><img src="'+p+'" alt="image-20251111091710490"></p><h3 id="_4-模组内部结构图" tabindex="-1">4. 模组内部结构图 <a class="header-anchor" href="#_4-模组内部结构图" aria-label="Permalink to &quot;4. 模组内部结构图&quot;">​</a></h3><h2 id="三、鲁班猫-2" tabindex="-1">三、鲁班猫 2 <a class="header-anchor" href="#三、鲁班猫-2" aria-label="Permalink to &quot;三、鲁班猫 2&quot;">​</a></h2><h3 id="_1-相关资料-2" tabindex="-1">1. 相关资料 <a class="header-anchor" href="#_1-相关资料-2" aria-label="Permalink to &quot;1. 相关资料&quot;">​</a></h3><p>这里我使用的是野火的鲁班猫 2 的开发板来学习，所以这里的电路以这块开发板为准：</p><ul><li>原理图在这里：<a href="https://gitee.com/LubanCat/ebf_lubancat_rk_hardware/raw/main/hardware/LubanCat-RK_%E9%80%89%E5%9E%8B%E6%89%8B%E5%86%8C_%E8%A7%84%E6%A0%BC%E4%B9%A6_%E7%A1%AC%E4%BB%B6%E8%B5%84%E6%96%99/%E9%B2%81%E7%8F%AD%E7%8C%AB2/20231201/LubanCat2_EBF410044V3R0_SCH_20240323.pdf" target="_blank" rel="noreferrer">LubanCat2_EBF410044V3R0_SCH_20240323.pdf</a></li><li>规格书在这里：<a href="https://gitee.com/LubanCat/ebf_lubancat_rk_hardware/raw/main/hardware/LubanCat-RK_%E9%80%89%E5%9E%8B%E6%89%8B%E5%86%8C_%E8%A7%84%E6%A0%BC%E4%B9%A6_%E7%A1%AC%E4%BB%B6%E8%B5%84%E6%96%99/%E9%B2%81%E7%8F%AD%E7%8C%AB2/%5B%E9%87%8E%E7%81%AB%5D%E9%B2%81%E7%8F%AD%E7%8C%AB2%E5%BC%80%E5%8F%91%E6%9D%BF%E7%A1%AC%E4%BB%B6%E8%A7%84%E6%A0%BC%E4%B9%A6_V1.2.2.pdf" target="_blank" rel="noreferrer">鲁班猫 2 硬件规格书</a></li></ul><h3 id="_2-mipi-csi-摄像头接口" tabindex="-1">2. MIPI CSI 摄像头接口 <a class="header-anchor" href="#_2-mipi-csi-摄像头接口" aria-label="Permalink to &quot;2. MIPI CSI 摄像头接口&quot;">​</a></h3><p>我们打开原理图 <a href="https://gitee.com/LubanCat/ebf_lubancat_rk_hardware/raw/main/hardware/LubanCat-RK_%E9%80%89%E5%9E%8B%E6%89%8B%E5%86%8C_%E8%A7%84%E6%A0%BC%E4%B9%A6_%E7%A1%AC%E4%BB%B6%E8%B5%84%E6%96%99/%E9%B2%81%E7%8F%AD%E7%8C%AB2/20231201/LubanCat2_EBF410044V3R0_SCH_20240323.pdf" target="_blank" rel="noreferrer">LubanCat2_EBF410044V3R0_SCH_20240323.pdf</a> 可以看到这里有两个 MIPI CSI 摄像头接口：</p><p><img src="'+s+'" alt="image-20251110195916353"></p><p>可以看到这两个接口的引脚顺序是一模一样的，只是用的 MIPI CSI 接口不同，前面的 OV8858 摄像头 FPC 接口的顺序也一样，所以最后接在哪一个上面都行，只要设备树资源对应就可以。</p><h2 id="四、camera-与-cpu" tabindex="-1">四、Camera 与 CPU <a class="header-anchor" href="#四、camera-与-cpu" aria-label="Permalink to &quot;四、Camera 与 CPU&quot;">​</a></h2><p>网上看到一个 Camera 与 CPU 模块图，刚好就是 RK3568 的，这里来分析一下：</p><p><img src="'+c+'" alt="image-20251111112842138"></p><p>MIPI 接口在系统的实现如上图所示，</p><p>（1）通常一个 camera 的模组如图所示，通常包括 Lens、Sensor、CSI 接口等，其中 CSI 接口用于视频数据的传输；</p><p>（2）SoC 的 Mipi 接口对接 Camera，并通过 I2C/SPI 控制 camera 模组；</p><p>（3）MIPI DPHY 提供了 4 Lane 的 Rx 接口，由 Sensor 提供 Clock，并通过四条数据 Lane 输入图像数据;</p><p>（4）DPHY 与 CSI-2 Host Contrller 之间通过 PPI（PHY-Protocol Interface）相连，该接口包括了控制，数据，时钟等多条信号；</p><p>（5）CSI-2 Host Contrller 通过 PPI 接口收到数据后进行解析，完成后通过 IDI(Image Data Interface)或者 IPI(Image Pixel Interface)输出到 SoC 的其他模块(VICAP 或 ISP，rk3568 是送至 VICAP 模块)；</p><p>（6）ISP 将处理过的图片输出到 MP 主通道或 SP 自身通道，SP 一般用来预览图片，SP 图片的最大分辨率比 MP 低；</p><p>（7）SoC 通过 APB Slave 总线控制 CSI-2 Host Contrller 的相关寄存器。</p><blockquote><p>参考资料：</p><p><a href="https://blog.csdn.net/qq21497936/article/details/134922307" target="_blank" rel="noreferrer">硬件开发笔记（十六）：RK3568 底板电路 mipi 摄像头接口原理图分析、mipi 摄像头详解_rk3568 dvp-CSDN 博客</a></p><p><a href="https://zhuanlan.zhihu.com/p/599531271" target="_blank" rel="noreferrer">(3 封私信) Camera | 2.MIPI、CSI 基础 - 知乎</a></p><p><a href="https://ldd.100ask.net/zh/13_V4L2/05_1.html" target="_blank" rel="noreferrer">05_MIPI 摄像头驱动程序分析 — Linux 设备驱动开发教程中心</a></p></blockquote>',41)])])}const E=e(h,[["render",_]]);export{C as __pageData,E as default};
